USE hms;
ALTER TABLE users MODIFY role ENUM('admin','receptionist','nurse','doctor','lab','pharmacist','cashier','records','chp','radiographer') NOT NULL;
ALTER TABLE visits MODIFY status ENUM('registered','triage','consultation','lab','imaging','procedure','pharmacy','billing','admitted','done') DEFAULT 'registered';
CREATE TABLE IF NOT EXISTS imaging_exams(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,modality ENUM('X-ray','Ultrasound','CT scan','Other') DEFAULT 'X-ray',price DECIMAL(10,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS imaging_orders(id INT AUTO_INCREMENT PRIMARY KEY,visit_id INT NOT NULL,exam_id INT NOT NULL,clinical_info VARCHAR(255),status ENUM('queued','reported','cancelled') DEFAULT 'queued',findings TEXT,impression TEXT,ordered_by INT,performed_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,reported_at DATETIME NULL,FOREIGN KEY(visit_id) REFERENCES visits(id),FOREIGN KEY(exam_id) REFERENCES imaging_exams(id));
CREATE TABLE IF NOT EXISTS procedures_catalog(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,price DECIMAL(10,2) DEFAULT 0);
CREATE TABLE IF NOT EXISTS procedure_orders(id INT AUTO_INCREMENT PRIMARY KEY,visit_id INT NOT NULL,proc_id INT NOT NULL,indication VARCHAR(255),status ENUM('queued','done','cancelled') DEFAULT 'queued',outcome TEXT,complications VARCHAR(255),consent TINYINT DEFAULT 0,ordered_by INT,performed_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,done_at DATETIME NULL,FOREIGN KEY(visit_id) REFERENCES visits(id),FOREIGN KEY(proc_id) REFERENCES procedures_catalog(id));
CREATE TABLE IF NOT EXISTS immunization_records(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,visit_id INT NULL,kind ENUM('vaccine','vitamin_a','deworming') NOT NULL,item VARCHAR(80) NOT NULL,dose_no INT NULL,given_at DATE NOT NULL,batch_no VARCHAR(40),next_due DATE NULL,notes VARCHAR(255),given_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq(patient_id,kind,item,dose_no),FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE IF NOT EXISTS nutrition_assessments(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,visit_id INT NULL,assessed_at DATETIME DEFAULT CURRENT_TIMESTAMP,weight_kg DECIMAL(5,1),height_cm DECIMAL(5,1),muac_mm INT NULL,oedema TINYINT DEFAULT 0,classification VARCHAR(60),advice VARCHAR(255),notes VARCHAR(255),assessed_by INT,FOREIGN KEY(patient_id) REFERENCES patients(id));
CREATE TABLE IF NOT EXISTS inv_items(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,category ENUM('Supplies','Consumables','Equipment') DEFAULT 'Supplies',unit VARCHAR(20),stock INT DEFAULT 0,reorder_level INT DEFAULT 5,location VARCHAR(60),serial VARCHAR(40),cond ENUM('good','needs repair','out of service') DEFAULT 'good');
CREATE TABLE IF NOT EXISTS inv_requisitions(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,qty INT NOT NULL,requested_by INT,dept_id INT NULL,note VARCHAR(200),status ENUM('pending','issued','rejected') DEFAULT 'pending',issued_qty INT NULL,issued_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,issued_at DATETIME NULL,FOREIGN KEY(item_id) REFERENCES inv_items(id));
CREATE TABLE IF NOT EXISTS inv_movements(id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,change_qty INT NOT NULL,type ENUM('receive','issue','adjust') NOT NULL,ref VARCHAR(80),by_user INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES inv_items(id));
